chrome.runtime.onMessage.addListener((u,i,t)=>{if(u.type==="NAVIGATE_TAB"&&u.url)return i.tab&&i.tab.id?(chrome.tabs.update(i.tab.id,{url:u.url},r=>{t({success:!0,tab:r})}),!0):(chrome.tabs.query({active:!0,currentWindow:!0},r=>{r[0]&&r[0].id&&chrome.tabs.update(r[0].id,{url:u.url},l=>{t({success:!0,tab:l})})}),!0);if(u.type==="OPEN_NEW_TAB"&&u.url)return chrome.tabs.create({url:u.url},r=>{t({success:!0,tab:r})}),!0;if(u.type==="GET_TAB_CONTEXT")return chrome.tabs.query({active:!0,currentWindow:!0},r=>{r[0]?t({url:r[0].url,title:r[0].title,id:r[0].id}):t({url:null,title:null,id:null})}),!0});
